function footerHtml(){const n=columnCount(),parts=[picker.serviceRows.length&&plural(picker.serviceRows.length,'servicio','servicios'),picker.tollRows.length&&plural(picker.tollRows.length,'peaje','peajes')].filter(Boolean).join(' · ');return`<div class="obx-picker-count"><b>${plural(n,'columna','columnas')}</b> · ${parts}</div><div><button class="obx-secondary" type="button" data-obx-picker-close>Cancelar</button><button class="obx-primary" type="button" data-obx-picker-export ${picker.busy||!n?'disabled':''}>${picker.busy?'Preparando…':'Exportar Excel'}</button></div>`}
