if(el=hit('[data-obx-preset]')){const p=picker.presets.find(x=>x.id===el.dataset.obxPreset);if(p){applyPreset(picker,p);refreshPicker();focusAfter(`[data-obx-preset="${p.id}"]`)}return}
if(el=hit('[data-obx-preset-del-yes]')){deletePreset(el.dataset.obxPresetDelYes);picker.presets=readPresets();picker.confirmDelete=null;refreshPicker('mine');return}
if(hit('[data-obx-preset-del-no]')){const id=picker.confirmDelete;picker.confirmDelete=null;refreshPicker('mine');focusAfter(`[data-obx-preset-del="${id}"]`);return}
