if(el=hit('[data-obx-move]')){const{order,sel}=setsOf(activeType()),key=el.dataset.obxKey,i=orderedSelected(order,sel).indexOf(key);if(i<0||!moveSelected(order,sel,key,i+Number(el.dataset.obxMove)))return;refreshPicker('order','quick','mine');const mv=d=>document.querySelector(`[data-obx-key="${key}"][data-obx-move="${d}"]`),same=mv(el.dataset.obxMove);(same&&!same.disabled?same:mv(-el.dataset.obxMove))?.focus();return}
if(el=hit('[data-obx-remove]')){const{sel}=setsOf(activeType()),list=orderedSelected(setsOf(activeType()).order,sel),i=list.indexOf(el.dataset.obxRemove);sel.delete(el.dataset.obxRemove);refreshPicker('groups');afterSelection();const next=list[i+1]||list[i-1];if(next)focusAfter(`[data-obx-remove="${next}"]`);return}
