function onPickerKeydown(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(picker?.saving){picker.saving=false;picker.presetName='';refreshPicker('mine');focusAfter('[data-obx-save-preset]');return}if(picker?.confirmDelete){const id=picker.confirmDelete;picker.confirmDelete=null;refreshPicker('mine');focusAfter(`[data-obx-preset-del="${id}"]`);return}closePicker();return}if(e.key!=='Tab')return;const list=[...e.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled)')].filter(el=>typeof el.getClientRects!=='function'||el.getClientRects().length),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
async function fetchServiceRows(baseRows){if(!baseRows.length)return[];const ids=baseRows.map(r=>r.service_id).filter(Boolean),rows=[];for(let start=0;start<ids.length;start+=250){const{data,error}=await db().rpc('get_operator_billing_export_rows_v2_km_v1',{p_service_ids:ids.slice(start,start+250)});if(error)throw error;rows.push(...(Array.isArray(data?.rows)?data.rows:[]))}const byId=new Map(rows.map(r=>[String(r.service_id),r]));if(ids.length!==baseRows.length||ids.some(id=>!byId.has(String(id))))throw Error('Algunos servicios cambiaron o ya no están disponibles. Actualizá Facturación antes de exportar; no se descargó un archivo parcial.');return ids.map(id=>byId.get(String(id)))}
function tollNamesFor(row,tolls){const source=quote(row).toll_source;if(!['actual','planned'].includes(source))throw Error('No se pudo determinar el origen de los peajes. Quitá la columna de nombres o actualizá Facturación.');const names=new Map();for(const t of tolls){if(String(t.service_id)!==String(row.service_id)||!['provider','both'].includes(t.payer_agent)||!(source==='actual'?t.source==='actual':['planned','manual'].includes(t.source)))continue;const name=text(t.toll_name_snapshot);if(name)names.set(name,(names.get(name)||0)+num(t.quantity))}return [...names].map(([name,qty])=>qty>1?name+' ×'+qty:name).join(' | ')}
async function attachTollNames(rows){const ids=rows.map(r=>r.service_id),all=[];for(let i=0;i<ids.length;i+=100){for(let start=0;;start+=500){const{data,error}=await db().from('operator_service_tolls').select('service_toll_id,service_id,toll_name_snapshot,source,payer_agent,quantity').in('service_id',ids.slice(i,i+100)).order('service_toll_id',{ascending:true}).range(start,start+499);if(error)throw error;all.push(...(data||[]));if((data||[]).length<500)break}}const groups=new Map();for(const toll of all){const id=String(toll.service_id);if(!groups.has(id))groups.set(id,[]);groups.get(id).push(toll)}return rows.map(row=>({...row,export_toll_names:tollNamesFor(row,groups.get(String(row.service_id))||[])}))}
/* Recorrido de los servicios enganchados (los demás usan el de la prestadora). Si falla, el Excel sale igual. */
async function attachChainModes(rows){if(!rows.length)return rows;try{const{data,error}=await db().rpc('list_operator_service_chain_route_modes_v1',{p_service_ids:rows.map(r=>r.service_id)});if(error)throw error;const m=data||{};const labels=await chainLabels(Object.keys(m));return rows.map(r=>m[r.service_id]?{...r,chain_route_mode:m[r.service_id],chain_label:labels[r.service_id]||''}:r)}catch(e){console.warn('[excel] enganches',e);return rows}}
/* Relevo: «Tramo 1: Ana (Móvil 7) → Estación X · Tramo 2: Luis (Móvil 12) · Entregado». Sin relevo, la celda queda vacía. */
async function attachRelays(rows){if(!rows.length)return rows;try{const ids=[...new Set(rows.map(r=>r.service_id).filter(Boolean))].slice(0,2000);const{data,error}=await db().rpc('list_operator_service_relays_v1',{p_service_ids:ids});if(error)throw error;const m=data||{};const truck=(l,p)=>[l&&`Móvil ${l}`,p].filter(Boolean).join(' · ');return rows.map(r=>{const x=m[r.service_id];if(!x)return r;const t1=[x.from_driver_name||'Primer chofer',truck(x.from_truck_label,x.from_truck_plate)].filter(Boolean).join(' · '),t2=[x.to_driver_name||'Segundo chofer',truck(x.to_truck_label,x.to_truck_plate)].filter(Boolean).join(' · ');return{...r,relay_label:`Tramo 1: ${t1} → ${x.exchange_address||'punto de intercambio'} · Tramo 2: ${t2} · ${x.handed_over?'Entregado':'Sin entregar'}`}})}catch(e){console.warn('[excel] relevos',e);return rows}}
/* «Viene de SRV-1» / «Sigue con SRV-2» / «Viene de SRV-1 · Sigue con SRV-3». Si no se puede leer, la celda queda vacía. */
async function chainLabels(ids){const out={};const list=ids.slice(0,300);await Promise.all(list.map(async id=>{try{const{data,error}=await db().rpc('get_operator_service_chain_v1',{p_service_id:id});if(error)throw error;const parts=[];if(data?.previous)parts.push(`Viene de ${data.previous.label||'otro servicio'}`);if(data?.next)parts.push(`Sigue con ${data.next.label||'otro servicio'}`);out[id]=parts.join(' · ')}catch(e){out[id]=''}}));return out}
async function confirmExport(){if(!picker||picker.busy)return;const serviceCols=selectedColumns('service'),tollCols=selectedColumns('toll');if(picker.serviceRows.length&&!serviceCols.length&&picker.tollRows.length&&!tollCols.length)return notify('Seleccioná al menos una columna para exportar','warning');if(picker.serviceRows.length&&!picker.tollRows.length&&!serviceCols.length)return notify('Seleccioná al menos una columna de servicios','warning');if(picker.tollRows.length&&!picker.serviceRows.length&&!tollCols.length)return notify('Seleccioná al menos una columna de peajes','warning');const job=picker;picker.busy=true;renderPicker();try{excessTotals=buildExcessTotals();if(serviceCols.length)await window.AuxiliosKmRounding?.load();let enriched=serviceCols.length?await fetchServiceRows(job.serviceRows):[];if(serviceCols.some(c=>c.id==='toll_names'))enriched=await attachTollNames(enriched);if(serviceCols.some(c=>c.id==='maps_route'))enriched=await attachChainModes(enriched);if(serviceCols.some(c=>c.id==='relay'))enriched=await attachRelays(enriched);if(picker!==job)return;const sheets=[],xm=job.extrasMode;if(enriched.length)sheets.push({name:'Servicios',columns:xm==='inline'||xm==='both'?withInlineExtras(serviceCols,enriched):serviceCols,rows:enriched});const extraRows=xm==='sheet'||xm==='both'?extrasSheetRows(enriched):[];if(extraRows.length)sheets.push({name:'Adicionales',columns:extrasSheetColumns,rows:extraRows});if(tollCols.length&&picker.tollRows.length)sheets.push({name:'Peajes',columns:tollCols,rows:picker.tollRows});const excessRows=job.includeExcess!==false?excessRowsFor(job):[];if(excessRows.length)sheets.push({name:'Excedentes',columns:excessColumns,rows:excessRows});if(!sheets.length)throw new Error('No hay columnas con datos para exportar.');const count=sheets.reduce((n,sheet)=>n+sheet.rows.length,0);await excel().downloadStyled({filename:fileBase(picker.S,picker.label),title:workbookTitle(picker.S),sheets:styledSheets(sheets,nowLabel(),filtersLabel(picker.S,picker.label)),detalle:`${count} registro${count===1?'':'s'} exportado${count===1?'':'s'}`});savePickerPreferences();closePicker()}catch(e){if(picker!==job)return;picker.busy=false;renderPicker();notify(e.message||'No se pudo exportar a Excel','error')}}
